          if (!room) return fail("ROOM_NOT_JOINED", "not in that room (see: agentmesh room list)");
          if (!room.durable) return fail("ROOM_NOT_DURABLE", "that room is ephemeral: a work board needs a durable room");
          const d = await boardAct(() => room.withdrawWork(args.item_id)); if (!d) return;
          res.writeHead(200, { "content-type": "application/json" });
