  "contacts.presence": {
    tool: async (a) => {
      const who = a.who === undefined ? undefined : (Array.isArray(a.who) ? a.who : [a.who]).map(String).filter(Boolean);
      let rows;
      try { ({ rows } = await whoCore(who)); }
      catch (e) { svcRefuse("contacts.presence", "UNAVAILABLE", `Presence could not be read: ${e?.message ?? e}`); }
      return { contacts: rows.map(presenceRow) };
    },
    command: async (input, out) => {
      const d = await SERVICE_IMPL["contacts.presence"].tool(input);
      if (out.json) return out.print(d);
      if (!d.contacts.length) {
        console.log("This agent lets nobody in yet, so there is nobody to look for. Name some: agentmesh contacts presence <handle>");
        return;
      }
      const pad = Math.min(40, Math.max(...d.contacts.map((r) => r.name.length)) + 2);
      for (const r of d.contacts) console.log(`⊙ ${r.name.padEnd(pad)} ${r.line}`);
      console.log(`\n"online" is the agent's state: its person may be away. A quiet agent still takes messages.`);
      pageLine(`${CONSOLE_URL}/people`);
    },
  },

  "owner.ask": {
    tool: async (a) => {
      const id = "owner.ask";
      const text = typeof a.text === "string" ? a.text.trim() : "";
      if (!a.settles && !text) svcRefuse(id, "INPUT_INVALID", "Say the question, or give settles.");
      if (text.length > MESH_TEXT_MAX) svcRefuse(id, "INPUT_INVALID", `That question is ${text.length} characters; a message takes at most ${MESH_TEXT_MAX}.`);
      let hosted;
      try { hosted = await ownerAgentTry(); }
      catch (e) { svcRefuse(id, "UNAVAILABLE", String(e?.message ?? e)); }
      if (!hosted) svcRefuse(id, "NOT_LINKED");
      const who = hosted.handle ?? hosted.agent_id;
      const choices = a.choices === undefined ? [] : (Array.isArray(a.choices) ? a.choices : [a.choices]);
      let d;
      try {
        // A ticket, not a wait: the person answers whenever they open the app,
        // and the answer lands in the inbox as a reply to request_id.
        d = await sessionApiTry("POST", "/send", { to: hosted.agent_id, ...askPayload(text, { choices, settles: a.settles ?? null }), timeout_ms: MESH_HOLD_MS }, { timeoutMs: MESH_RECEIPT_CAP_MS });
      } catch (e) {
        if (e?.code === "AGENT_UNAVAILABLE" && e.details?.captured) {
          return withSome({ to: who, held: true, request_id: a.settles ? undefined : (e.details.request_id ?? undefined), settled: a.settles ?? undefined });
        }
        if (e?.code === "LOCAL_TIMEOUT") svcRefuse(id, "UNAVAILABLE", `Not confirmed: ${e.message}, so I can't tell whether the question reached the app. Ask in this chat as well; if the app shows it, its answer lands in messages_inbox.`);
        return meshRefusal(id, e);
      }
      if (a.settles) return { to: who, settled: String(a.settles) };
      return withSome({ to: who, request_id: d.payload?.request_id ?? d.request_id ?? undefined, held: false });
    },
    command: async (input, out) => cmdAskOwner(input.text ?? "", { choice: input.choices ?? [], settle: input.settles, wait: input.wait || undefined, json: out.json }),
  },

  "identity.me": {
    tool: async () => {
      if (rosterIsNode() && !agentContext()) {
        // Read, never minted: listing the roster is not consent to create an
        // identity in a folder that has none yet.
        const agents = rosterFolderNames().map((n) => withSome({ name: n, agent_id: stateRead(join(agentDirOf(n), "identity.json"), null, `${n}/identity.json`)?.public_key ?? undefined }));
        return { agents, running: sessionAlive() };
      }
      // Signed in by agentmesh join with no credential of its own: this
      // computer acts as that agent, through AgentMesh (placeMode).
      const place = placeMode();
      if (place) {
        return withSome({
          agent_id: place.agent,
          name: place.name ?? (place.handle ? place.handle.split(".")[0] : undefined),
          handle: place.handle ?? undefined,
          acting_as: `${placeWho(place)}, signed in on this computer (${place.machine}) with agentmesh join; every agentmesh tool and command here acts as that agent through AgentMesh, and its mail is kept there.`,
          can_send: true,
          credential: "the sign-in (place.json); this computer needs no credential of its own",
          running: true,
          adapter: await adapterVersionNote(),
        });
      }
      if (!existsSync(join(stateDir(), "identity.json"))) svcRefuse("identity.me", "NO_IDENTITY");
      const identity = loadIdentity();
      // A local read first (2026-10-10): the handle this machine verified for
      // this key in the last day answers at once. Only an agent with no such
      // record asks the naming service, and not for long.
      const last = stateRead(NAMED_FILE(), null, "the last verified handle (named.json)");
      const lastAt = Date.parse(last?.checked_at ?? "");
      const known = last?.agent_id === identity.public_key && isStandardHandle(last?.handle) && Number.isFinite(lastAt) && Date.now() - lastAt < NAMED_RECORD_TRUST_MS
        ? last.handle : null;
      let handle = known;
      if (!handle) {
        try {
          const r = await fetch(`${REGISTRAR}/api/resolve?agent_id=${encodeURIComponent(identity.public_key)}`, { signal: AbortSignal.timeout(Math.min(6000, MCP_BASE_MS / 2)) });
          if (r.ok) handle = (await r.json())?.card?.handle ?? null;
        } catch { /* the naming service did not answer; the rest still stands */ }
      }
      // Whether this agent may send at all (the naming rule), said up front
      // so a model learns it here rather than from its first refused send.
      const unnamed = known ? null : await requireNamed(identity);
      const waiting = waitingNote();
      const adapter = await adapterVersionNote();
      // A name is not enough to send (2026-10-10: identity me said "can send:
      // yes" for a named key with no credential, and every send then failed).
      // The tools send through this computer's node, which needs a credential
      // and must be running; say which is missing and the one fix.
      const running = sessionAlive();
      const cred = credsProbe();
      // A running node holds a working credential (it could not have
      // connected otherwise, and on a fleet host its credential file may be
      // one this process cannot read), so only a stopped node is checked.
      const blocked = unnamed || running ? null
        : cred.kind === "none" ? { missing: "credential", why: noCredentialWords(cred.reason ?? "no credential file") }
          : { missing: "inbox", why: "This agent's node is not running on this computer, so nothing can be sent or received as it. Start it with: agentmesh start --inbox" };
      return withSome({
        agent_id: identity.public_key,
        // Its name is the handle's first part; before it has one, the name it goes by here.
        name: (handle ? handle.split(".")[0] : knownAgentName()) ?? undefined,
        handle: handle ?? undefined,
        can_send: !unnamed && !blocked,
        why_not: unnamed?.error ?? blocked?.why,
        missing: unnamed ? "name" : blocked?.missing,
        proposed_handle: unnamed?.proposed_handle,
        get_a_name: unnamed?.code === "NOT_NAMED" ? "Ask the person for their email and the name they want, call names_claim with both, then names_confirm with the code they are emailed." : undefined,
        credential: cred.kind === "creds_file" ? `this computer's own (${cred.path})` : cred.kind === "none" ? "none" : undefined,
        running,
        waiting,
        adapter,
      });
    },
    command: async (_input, out) => {
      const d = await SERVICE_IMPL["identity.me"].tool({});
      if (out.json) return out.print(d);
      if (d.acting_as) {
        console.log(`acting as  ${d.acting_as}`);
        console.log(`can send   yes`);
        if (d.adapter?.update) console.log(`adapter    ${d.adapter.version}; ${d.adapter.update}`);
        return;
      }
      if (d.agent_id) {
        console.log(`agent      ${d.agent_id}`);
        console.log(`handle     ${d.handle ?? "(none yet)"}`);
        console.log(`can send   ${d.can_send ? "yes" : `no: ${d.why_not}`}`);
        if (d.waiting) console.log(`waiting    ${d.waiting.names.join(", ")}: agentmesh contacts waiting`);
        if (d.adapter?.update) console.log(`adapter    ${d.adapter.version}; ${d.adapter.update}`);
        console.log("");
      }
      cmdStatus();
    },
  },

