// An old word a definition renamed (send is messages send now): its page
// opens with the notice and it leaves the topic lists for its new family.
// It still answers until its window closes (oldCommand).
for (const [words, r] of Object.entries(RENAMED_COMMANDS)) {
  if (words.includes(" ") || !HELP[words]) continue;
  HELP[words] = { ...HELP[words], tier: "renamed", s: `renamed: ${r.to}`, body: `${renamedNotice(r.old, r.to, r.stops)}\n\n${HELP[words].body}` };
}

const short = (word) => `  agentmesh ${word.padEnd(12)} ${HELP[word].s}`;

/** A command's examples, under its story: the line to type, then what it
 *  does, for the commands whose usage line alone does not show how they are
 *  used. Nothing for a command that has none. */
const examplesText = (examples) => examples?.length
  ? `\n\n  for example:\n` + examples.map((e) => `    ${e.run}\n        ${e.says}`).join("\n")
  : "";

/** Where releases live. The adapter never read this before: a machine could
 *  sit on a two-month-old version with nothing ever saying so. Overridable so
 *  a test can stand in for the bucket. */
const RELEASES_URL = process.env.MESH_RELEASES_URL ?? "https://storage.googleapis.com/agentmesh-releases";

/** Semver order, enough for release numbers: a > b. */
function newerThan(a, b) {
  const pa = String(a).split(".").map(Number);
  const pb = String(b).split(".").map(Number);
  for (let i = 0; i < 3; i++) if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) > (pb[i] ?? 0);
  return false;
}

/** The one line that installs or updates the adapter on this machine: the
 *  installer in install/ (published beside the tarballs by
 *  tools/release-adapter.sh), which stops and restarts a running inbox daemon
 *  around the install. PowerShell on Windows, sh everywhere else. */
function updateCommand(platform = process.platform) {
  return platform === "win32"
    ? `irm ${RELEASES_URL}/mesh-adapter-install.ps1 | iex`
    : `curl -fsSL ${RELEASES_URL}/mesh-adapter-install.sh | sh`;
}

/** One line under the short help when the bucket names a newer version than
 *  the one running, with the install command. Silent on any failure: a help
 *  screen must never wait on the network or blame it. */
async function noteNewerVersion() {
  try {
    const r = await fetch(`${RELEASES_URL}/mesh-adapter-latest.txt`, { signal: AbortSignal.timeout(1500) });
    if (!r.ok) return;
    const latest = (await r.text()).trim();
    if (!/^\d+\.\d+\.\d+$/.test(latest) || !newerThan(latest, VERSION)) return;
    console.log(`\nA newer version, ${latest}, is out. Update with:\n  ${updateCommand()}`);
  } catch {
    /* offline, slow, or the bucket is away: say nothing */
  }
}

/** Where the newest version this machine has heard of is kept, so a model's
 *  identity_me and the MCP server's instructions can say "update available"
 *  without asking the bucket every time. */
const UPDATE_CHECK_FILE = () => join(stateDir(), "update_check.json");
const UPDATE_CHECK_TTL_MS = 6 * 3600_000;

/** This adapter's version, and the newest one released when it is newer, with
 *  the command that installs it. Read from the cache when it is fresh, else
 *  asked of the release bucket for at most 1.5 s; silent on any failure. A
 *  machine ran 0.89.1 for weeks while 0.97 was out and nothing told anyone
 *  (2026-10-10). */
async function adapterVersionNote() {
  let latest = null;
  try {
    const c = stateRead(UPDATE_CHECK_FILE(), null, "the last release check (update_check.json)");
    if (c && Date.now() - Date.parse(c.checked_at ?? "") < UPDATE_CHECK_TTL_MS && /^\d+\.\d+\.\d+$/.test(c.latest ?? "")) latest = c.latest;
  } catch { /* asked below */ }
  if (!latest) {
    try {
      const r = await fetch(`${RELEASES_URL}/mesh-adapter-latest.txt`, { signal: AbortSignal.timeout(1500) });
      const t = r.ok ? (await r.text()).trim() : "";
      if (/^\d+\.\d+\.\d+$/.test(t)) {
        latest = t;
        try { stateWrite(UPDATE_CHECK_FILE(), { latest, checked_at: new Date().toISOString() }); } catch { /* the answer still stands */ }
      }
    } catch { /* offline, slow, or the bucket is away */ }
  }
  if (!latest || !newerThan(latest, VERSION)) return { version: VERSION, ...(latest ? { latest } : {}) };
  // The installer's one line (install/install.mjs): it stops a running inbox
  // daemon, installs, and starts the daemon again on the new version, so only
  // this session is left to restart.
  const command = updateCommand();
  return { version: VERSION, latest, update: `update available: ${latest} is out (this is ${VERSION}). Install it with: ${command} (it restarts the inbox daemon itself), then restart this session so it runs the new version too.`, update_command: command };
}

function printShortHelp({ face = true } = {}) {
  if (face) console.log(wordmark().join("\n") + "\n");
  else console.log(`agentmesh ${VERSION} — your agent's door to the mesh`);
  console.log(`(one tool, three names: agentmesh, mesh, mesh-adapter)

getting on
${["up", "join", "mcp"].map(short).join("\n")}

every day
${["messages", "contacts", "owner", "rooms", "feeds", "invite", "identity", "names"].map(short).join("\n")}

your front door
  agentmesh contacts waiting       who is waiting to reach you
  agentmesh contacts admit|block   let a sender in, or keep them out

more
  agentmesh help <command>   one command's full story (any command above)
  agentmesh help market      charging, paying, agreements, postings (${Object.values(HELP).filter((h) => h.tier === "market").length} commands)
  agentmesh help trust       vetting strangers, reputation, key pins (${Object.values(HELP).filter((h) => h.tier === "trust").length})
  agentmesh help ops         credentials and diagnostics (${Object.values(HELP).filter((h) => h.tier === "ops").length})
  agentmesh help start       every way onto the mesh (${Object.values(HELP).filter((h) => h.tier === "start").length})
  agentmesh help --all       everything on one page

what the adapter does, in plain words: https://agentmesh.ai/connect/adapter.html`);
}

function printTopicHelp(topic) {
  const words = Object.keys(HELP).filter((w) => HELP[w].tier === topic);
  console.log(`agentmesh ${VERSION} · ${HELP_TOPICS[topic]}\n`);
  console.log(words.map(short).join("\n"));
  console.log(`\n  agentmesh help <command>   the full story of any of these`);
}

function printFullHelp() {
  console.log(`agentmesh ${VERSION} — the thin reference AgentMesh node`);
  for (const topic of Object.keys(HELP_TOPICS)) {
    console.log(`\n${HELP_TOPICS[topic]}`);
    for (const w of Object.keys(HELP).filter((x) => HELP[x].tier === topic)) {
      console.log(HELP[w].body.split("\n").map((l) => `  ${l}`).join("\n"));
    }
  }
}

async function cmdHelp(sub, o) {
  // The registry itself, for the page on the website that explains every
  // command in plain words: built from this, so the two can never disagree.
  if (o?.json) return console.log(JSON.stringify({
    version: VERSION,
    topics: HELP_TOPICS,
    commands: Object.entries(HELP).map(([word, h]) => ({ word, tier: h.tier, summary: h.s, story: h.body, ...(h.examples ? { examples: h.examples } : {}) })),
  }, null, 2));
  if (o?.all) return printFullHelp();
  const word = String(sub ?? "").trim();
  // The short page is the one screen every user sees, so it is the one place
  // to say a newer version exists. Not on a command's page or the full
  // reference, which are read for their content.
  if (!word) return printShortHelp(), noteNewerVersion();
  if (HELP[word]) return console.log(HELP[word].body + examplesText(HELP[word].examples));
  // An old family a definition renamed (room to rooms): say so, then its help.
  const moved = renamedFamily(word);
  if (moved && HELP[moved.service]) {
    console.error(renamedNotice(`agentmesh ${word}`, `agentmesh ${moved.service}`, moved.stops));
    return console.log(HELP[moved.service].body + examplesText(HELP[moved.service].examples));
  }
  if (HELP_TOPICS[word]) return printTopicHelp(word);
  fail(`no command or topic named "${word}" — try: agentmesh help`);
}

/** Whether the first word asks for the version. */
function isVersionWord(word) {
  return ["--version", "-v", "-version", "version"].includes(String(word ?? "").toLowerCase());
}

const [cmd, ...args] = process.argv.slice(2);
const { opts, rest } = parseFlags(args);
if (opts.anchorWebfinger) ANCHOR_WEBFINGER_BASE = opts.anchorWebfinger;
if (opts.as) sessionAgentName = opts.as;
// A one-shot command on a node of many speaks for ONE agent: its local API
// calls go under /agents/<name>, and everything it reads or signs with (the
// identity, the roster, the inbox) is that agent's folder. Bound here, once,
// for the rest of this process, so no command has to know the node exists.
if (sessionAgentName && rosterIsNode()) {
  if (!AGENT_NAME_RE.test(sessionAgentName) || !existsSync(agentDirOf(sessionAgentName))) {
    console.error(`no agent named ${sessionAgentName} under ${agentsDir()}; the roster: ${rosterFolderNames().join(", ") || "(empty)"}`);
    process.exit(1);
  }
  agentScope.enterWith({ name: sessionAgentName, dir: agentDirOf(sessionAgentName), identity: null });
}
try {
  // The version, alone on a line, for a script or a person checking an install,
  // first so no command word can shadow it. Every spelling people type
  // (--version, -v, -V, -version, version): our own emails said --version, and
  // a person who types `version` means the same.
  if (isVersionWord(cmd)) console.log(VERSION);
  else if (cmd === "start") await cmdStart(opts);
  else if (cmd === "agent") await cmdAgent(rest[0], rest.slice(1), opts);
  else if (cmd === "explain") cmdExplain(opts);
  else if (cmd === "pack") await cmdPack(rest[0], opts);
  else if (cmd === "join") await cmdJoin(opts);
  else if (cmd === "place") await cmdPlace(rest[0], rest.slice(1), opts);
  else if (cmd === "bootstrap") await cmdBootstrap(rest[0]);
  else if (cmd === "up") await cmdUp(rest[0], opts);
  else if (cmd === "mcp") await cmdMcp(args);
  // The mesh's old commands (platform-services/*.json, `old`): each still runs
  // as it always did, flags and all, with the notice naming its new command
  // until its window closes, and then refuses with the new name.
  else if (cmd === "pair") { oldCommand("pair"); await cmdPair(rest[0], rest[1]); }
  else if (cmd === "send") { oldCommand("send"); await cmdSend(rest[0], rest.slice(1).join(" "), opts.wait ?? 0, opts); }
  else if (cmd === "knock") { oldCommand("knock"); await cmdKnock(rest[0]); }
  else if (cmd === "who") { oldCommand("who"); await cmdWho(opts); }
  else if (cmd === "invite") await cmdInvite(rest[0], opts);
  else if (cmd === "request-stream") await cmdRequestStream(rest[0], rest.slice(1).join(" "), opts);
  else if (cmd === "link") await cmdLink(rest[0]);
  else if (cmd === "inbox") { oldCommand("inbox"); await cmdInbox(opts.json, opts.follow); }
  else if (cmd === "ask-owner") { oldCommand("ask-owner"); await cmdAskOwner(rest.join(" "), opts); }
  else if (cmd === "reply") { oldCommand("reply"); await cmdReply(rest[0], rest.slice(1).join(" "), opts); }
  else if (cmd === "ack") { oldCommand("ack"); await cmdAck(rest); }
  // The platform services and the mesh's own requests (platform-services/
  // *.json), and the old commands a definition renamed, which answer with the
  // notice for their window.
  else if (isServiceCommand(cmd)) await cmdService(cmd, args[0], args.slice(1));
  else if (cmd === "allowance") await cmdAllowance(rest[0], rest.slice(1), opts);
  else if (cmd === "screening") await cmdScreening(rest[0], rest.slice(1), opts);
  else if (cmd === "describe") await cmdDescribe(rest[0], rest.slice(1));
  else if (cmd === "data-use") await cmdDataUse(rest[0], rest.slice(1), opts);
  else if (cmd === "price") await cmdPrice(rest[0], rest.slice(1), opts);
  else if (cmd === "agree") await cmdAgree(rest[0], rest.slice(1), opts);
  else if (cmd === "engage") await cmdEngage(rest[0], rest.slice(1), opts);
  else if (cmd === "rfp") await cmdRfp(rest[0], rest.slice(1), opts);
  else if (cmd === "probe") await cmdProbe(rest[0], rest.slice(1), opts);
  else if (cmd === "interview") await cmdInterview(rest[0], opts);
  else if (cmd === "review") await cmdReview(rest[0], rest.slice(1), opts);
  else if (cmd === "value") await cmdValue(rest[0], rest.slice(1), opts);
  else if (cmd === "reputation") await cmdReputation(rest[0], rest.slice(1), opts);
  else if (cmd === "pins") cmdPins(rest[0], rest.slice(1));
  else if (cmd === "system-fault") await cmdSystemFault(rest[0], rest[1], opts);
  else if (cmd === "system-ok") await cmdSystemOk(rest[0]);
  else if (cmd === "proxy") cmdProxy(rest[0]);
  else if (cmd === "trace") await cmdTrace(rest[0], rest.slice(1), opts);
  else if (cmd === "diag") await cmdDiag(rest[0], rest.slice(1), opts);
  else if (cmd === "doctor") await cmdDoctor(rest, opts);
  else if (cmd === "status") { oldCommand("status"); cmdStatus(); }
  else if (cmd === "credential") await cmdCredential(rest[0]);
  else if (cmd === "key") await cmdKey(rest[0], opts);
  else if (cmd === "mesh") await cmdMesh(args);
  // An old family a definition renamed (room to rooms): after every command
  // that still runs its own code, so rfp, interview, review and value keep
  // their own words (respond, award, --self) with their notices.
  else if (renamedFamily(cmd)) await cmdRenamedFamily(cmd, args);
  else if (cmd === "--help" || cmd === "-h" || cmd === "help") await cmdHelp(rest[0], opts);
  else if (!cmd) await cmdHelp();
  else {
    // An unknown command is an error, not a shrug: name it, show the way in,
    // and exit nonzero so a script notices.
    console.error(`unknown command "${cmd}" — the everyday commands:\n`);
    printShortHelp({ face: false });
    process.exitCode = 1;
  }

  // The artifact-address rule for families whose page is fixed, applied here
  // once so no command forgets its own address. Commands whose page depends
  // on their own output (status, join, pair, the room verbs) print theirs at
  // the tail instead. A refusal threw before this line; --json stays clean.
  if (!opts.json && process.exitCode !== 1) {
    const CONTACT_PAGES = { review: "/waiting", approve: "/waiting", list: "/agents", allow: "/agents", block: "/agents", remove: "/agents" };
    const page =
      cmd === "who" || cmd === "invite" ? "/people"
      : cmd === "portfolio" ? "/portfolio"
      : cmd === "agree" ? "/buying"
      : cmd === "engage" || cmd === "value" || cmd === "review" ? "/engagements"
      : cmd === "rfp" ? "/rfp"
      : cmd === "account" && rest[0] === "status" ? "/account"
      : cmd === "contacts" ? (CONTACT_PAGES[rest[0]] ?? null)
      : null;
    if (page) pageLine(`${CONSOLE_URL}${page}`);
    else if (cmd === "interview" && rest[0] && !opts.self) pageLine(agentPage(rest[0]));
    else if (cmd === "reputation" && rest[0] === "report") {
      try { pageLine(agentPage(rest[1] ?? loadIdentity().public_key)); } catch { /* no identity, no page */ }
    }
  }
} catch (e) {
  // The sentinel from fail(): the message is already on stderr and the exit
  // code is already 1. Saying anything more here would print the refusal twice.
  // Deliberately NOT re-calling fail(), which would throw out of this catch and
  // surface as an unhandled exception with a stack trace attached to what is
  // an ordinary refusal.
  if (!isStop(e)) {
    console.error(`error: ${e?.message ?? e}`);
    process.exitCode = 1;
  }
}
